use crate::menu::*;
use crate::menu_render::*;
fn view()->View {View {revision:4,scope:"Project [ws-1] / Shell [pane-1]".into(),breadcrumb:"Main / Close…".into(),rows:vec![Row{label:"Cancel".into(),disabled:None},Row{label:"Confirm 猫 close".into(),disabled:None}],selected:1,details:vec!["target /tmp/猫/very-long-name\x1b[2J\r\nnext".into()],status:"Ready".into(),scroll:0,expanded:false,labels:LabelStyle::Both,editor:None}}
#[test] fn render_structure_selection_and_terminal_safety(){let out=render(&view(),64,12);assert!(out.contains("Main / Close…"));assert!(out.contains("> Confirm 猫 close"));assert!(out.contains("Cross"));assert!(out.contains("Circle"));assert!(!out.contains('\x1b'));assert!(!out.contains('\r'));assert!(out.contains("target"));}
#[test] fn width_clipping_and_small_viewports(){assert_eq!(clip("猫ab",3),"猫a");assert_eq!(clip("e\u{301}猫",1),"e\u{301}");for width in [1,4,12,40] {let out=render(&view(),width,8);assert!(out.lines().all(|l|unicode_width::UnicodeWidthStr::width(l)<=width));assert!(out.lines().count()<=8);}let out=render(&view(),24,8);assert!(out.contains("> Confirm"));}
#[test] fn expanded_details_show_full_target_over_scroll(){let mut v=view();v.expanded=true;v.details=vec!["/tmp/long/猫/target/with/a/name".into()];let first=render(&v,20,8);assert!(first.contains("/tmp/long/猫"));v.scroll=1;let next=render(&v,20,8);assert_ne!(first,next);assert!(next.contains("target"));}
#[test] fn external_controls_are_visible_text_and_legends_follow_preference(){assert_eq!(sanitize("a\x1b\n\t\u{7f}b"),"a� � �b");let mut v=view();v.labels=LabelStyle::Xbox;let out=render(&v,80,12);assert!(out.contains("A Select"));assert!(!out.contains("Cross"));v.labels=LabelStyle::PlayStation;assert!(render(&v,80,12).contains("✕ Cross"));}
